{"file_path":"src/cli.js","content":"#!/usr/bin/env node

import { readFileSync } from 'fs'

const mode = process.argv[2]

// Validate mode
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Read and parse input
const input = readFileSync(0, 'utf8')
const parts = input.split(/%%%\n?/).map(part => {
  const lines = part.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
})

if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

const [mine, base, theirs] = parts

// LCS algorithm using greedy strategy
function findLCS(baseDoc, sideDoc) {
  const matches = []
  let baseIdx = 0
  let sideIdx = 0

  while (baseIdx < baseDoc.length && sideIdx < sideDoc.length) {
    if (baseDoc[baseIdx] === sideDoc[sideIdx]) {
      matches.push({ baseIdx, sideIdx })
      baseIdx++
      sideIdx++
    } else {
      const baseRemaining = baseDoc.length - baseIdx
      const sideRemaining = sideDoc.length - sideIdx

      // Advance the side with more remaining lines, prefer base on tie
      if (sideRemaining > baseRemaining) {
        sideIdx++
      } else {
        baseIdx++
      }
    }
  }

  return matches
}

// Extract changes from LCS matches
function getChanges(baseDoc, sideDoc) {
  const lcs = findLCS(baseDoc, sideDoc)
  const changes = []

  let prevBaseEnd = 0
  let prevSideEnd = 0

  for (const match of lcs) {
    if (match.baseIdx > prevBaseEnd || match.sideIdx > prevSideEnd) {
      changes.push({
        baseStart: prevBaseEnd,
        baseEnd: match.baseIdx,
        sideStart: prevSideEnd,
        sideEnd: match.sideIdx
      })
    }
    prevBaseEnd = match.baseIdx + 1
    prevSideEnd = match.sideIdx + 1
  }

  // Handle the tail
  if (prevBaseEnd < baseDoc.length || prevSideEnd < sideDoc.length) {
    changes.push({
      baseStart: prevBaseEnd,
      baseEnd: baseDoc.length,
      sideStart: prevSideEnd,
      sideEnd: sideDoc.length
    })
  }

  return changes
}

// Build side content for a region by applying changes
function buildSideContent(baseDoc, sideDoc, baseStart, baseEnd, changes) {
  const relevantChanges = changes
    .filter(c => c.baseEnd > baseStart && c.baseStart < baseEnd)
    .sort((a, b) => a.baseStart - b.baseStart)

  const result = []
  let baseIdx = baseStart

  for (const change of relevantChanges) {
    if (change.baseStart > baseIdx) {
      result.push(...baseDoc.slice(baseIdx, change.baseStart))
    }
    result.push(...sideDoc.slice(change.sideStart, change.sideEnd))
    baseIdx = change.baseEnd
  }

  if (baseIdx < baseEnd) {
    result.push(...baseDoc.slice(baseIdx, baseEnd))
  }

  return result
}

// Get changes for both sides
const mineChanges = getChanges(base, mine)
const theirsChanges = getChanges(base, theirs)

// Combine and sort changes by base start, mine first on ties
const allChanges = [
  ...mineChanges.map(c => ({ ...c, side: 'mine' })),
  ...theirsChanges.map(c => ({ ...c, side: 'theirs' }))
].sort((a, b) => {
  if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
  return a.side === 'mine' ? -1 : 1
})

// Group changes into regions
const regions = []
let changeIdx = 0

if (allChanges.length === 0) {
  // No changes, entire document is stable
  regions.push({
    type: 'stable',
    baseStart: 0,
    baseEnd: base.length
  })
} else {
  // Process regions
  let basePos = 0

  while (changeIdx < allChanges.length) {
    const firstChange = allChanges[changeIdx]

    // Add stable region before this change
    if (firstChange.baseStart > basePos) {
      regions.push({
        type: 'stable',
        baseStart: basePos,
        baseEnd: firstChange.baseStart
      })
      basePos = firstChange.baseStart
    }

    // Start a new change region
    let regionEnd = firstChange.baseEnd
    const regionChanges = [firstChange]
    changeIdx++

    // Absorb overlapping changes
    while (changeIdx < allChanges.length && allChanges[changeIdx].baseStart <= regionEnd) {
      const nextChange = allChanges[changeIdx]
      regionEnd = Math.max(regionEnd, nextChange.baseEnd)
      regionChanges.push(nextChange)
      changeIdx++
    }

    // Create change region
    const mineChangesInRegion = regionChanges.filter(c => c.side === 'mine')
    const theirsChangesInRegion = regionChanges.filter(c => c.side === 'theirs')

    regions.push({
      type: 'change',
      baseStart: firstChange.baseStart,
      baseEnd: regionEnd,
      mineChanges: mineChangesInRegion,
      theirsChanges: theirsChangesInRegion
    })

    basePos = regionEnd
  }

  // Add final stable region if needed
  if (basePos < base.length) {
    regions.push({
      type: 'stable',
      baseStart: basePos,
      baseEnd: base.length
    })
  }
}

// Resolve regions
let hasConflict = false
const output = []
const regionOutputs = []

for (const region of regions) {
  if (region.type === 'stable') {
    const lines = base.slice(region.baseStart, region.baseEnd)
    output.push(...lines)
    regionOutputs.push(`stable ${lines.length}`)
  } else {
    // Change region
    const baseLines = base.slice(region.baseStart, region.baseEnd)
    const mineLines = buildSideContent(base, mine, region.baseStart, region.baseEnd, region.mineChanges)
    const theirsLines = buildSideContent(base, theirs, region.baseStart, region.baseEnd, region.theirsChanges)

    // Resolve
    if (region.mineChanges.length === 0 && region.theirsChanges.length === 0) {
      // No changes, shouldn't happen
      output.push(...baseLines)
      regionOutputs.push(`stable ${baseLines.length}`)
    } else if (region.mineChanges.length === 0) {
      // Only theirs changed
      output.push(...theirsLines)
      regionOutputs.push(`theirs ${theirsLines.length}`)
    } else if (region.theirsChanges.length === 0) {
      // Only mine changed
      output.push(...mineLines)
      regionOutputs.push(`mine ${mineLines.length}`)
    } else if (mineLines.join('\n') === theirsLines.join('\n')) {
      // Same change on both sides
      output.push(...mineLines)
      regionOutputs.push(`both ${mineLines.length}`)
    } else if (mineLines.join('\n') === baseLines.join('\n')) {
      // Only theirs changed (even though both have changes)
      output.push(...theirsLines)
      regionOutputs.push(`theirs ${theirsLines.length}`)
    } else if (theirsLines.join('\n') === baseLines.join('\n')) {
      // Only mine changed (even though both have changes)
      output.push(...mineLines)
      regionOutputs.push(`mine ${mineLines.length}`)
    } else {
      // Conflict
      hasConflict = true
      if (mode === 'regions') {
        regionOutputs.push(`conflict mine=${mineLines.length} base=${baseLines.length} theirs=${theirsLines.length}`)
      } else {
        output.push('<<<<<<< mine')
        output.push(...mineLines)
        if (mode === 'merge') {
          output.push('||||||| base')
          output.push(...baseLines)
        }
        output.push('=======')
        output.push(...theirsLines)
        output.push('>>>>>>> theirs')
      }
    }
  }
}

// Output
if (mode === 'regions') {
  for (const line of regionOutputs) {
    process.stdout.write(line + '\n')
  }
} else {
  for (const line of output) {
    process.stdout.write(line + '\n')
  }
}

process.exit(hasConflict ? 1 : 0)
"}

