{"file_path":"src/diff3.js","content":"/**
 * Three-way merge over whole lines.
 */

/**
 * Longest common subsequence between two arrays of lines, returned as the list
 * of matched index pairs. Ties are broken towards the earliest matches: walking
 * from the start, a match is taken whenever the current lines are equal, and
 * otherwise the side whose remaining subsequence is at least as long advances,
 * the base being preferred when the two are equal.
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // suffix[i][j] = length of the LCS of base[i..] and side[j..]
  const suffix = new Array(n + 1)
  for (let i = 0; i <= n; i++) suffix[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = suffix[i]
    const next = suffix[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (suffix[i + 1][j] >= suffix[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Every stretch the subsequence does not cover, as a run of base lines replaced
 * by a run of the side's lines.
 */
export function changes(base, side) {
  const matches = lcsMatches(base, side)
  const result = []
  let bi = 0
  let si = 0
  const emit = (baseEnd, sideEnd) => {
    if (baseEnd > bi || sideEnd > si) {
      result.push({ baseStart: bi, baseEnd, sideStart: si, sideEnd })
    }
  }
  for (const [mb, ms] of matches) {
    emit(mb, ms)
    bi = mb + 1
    si = ms + 1
  }
  emit(base.length, side.length)
  return result
}

/**
 * The regions of a three-way merge, in base order. Each region is either
 * `{ kind: 'stable', lines }` or a changed region carrying the three candidate
 * line runs and its resolution.
 */
export function merge(mine, base, theirs) {
  const all = []
  for (const c of changes(base, mine)) all.push({ ...c, side: 'mine' })
