    stable(pos, start)
    pos = end

    const baseLines = base.slice(start, end)
    const sideLines = (name, doc) => {
      const own = group.filter(c => c.side === name)
      if (own.length === 0) return baseLines.slice()
      let minBase = Infinity
      let maxBase = -Infinity
      let minSide = Infinity
      let maxSide = -Infinity
      for (const c of own) {
        if (c.baseStart < minBase) minBase = c.baseStart
        if (c.baseEnd > maxBase) maxBase = c.baseEnd
        if (c.sideStart < minSide) minSide = c.sideStart
        if (c.sideEnd > maxSide) maxSide = c.sideEnd
      }
      return doc.slice(minSide - (minBase - start), maxSide + (end - maxBase))
    }

    const mineLines = sideLines('mine', mine)
    const theirsLines = sideLines('theirs', theirs)
    const mineTouched = group.some(c => c.side === 'mine')
    const theirsTouched = group.some(c => c.side === 'theirs')

    let resolution
    if (group.length === 1) {
      resolution = mineTouched ? 'mine' : 'theirs'
    } else if (same(mineLines, theirsLines)) {
      resolution = mineTouched && theirsTouched ? 'both' : mineTouched ? 'mine' : 'theirs'
    } else if (same(mineLines, baseLines)) {
      resolution = 'theirs'
    } else if (same(theirsLines, baseLines)) {
      resolution = 'mine'
    } else {
      resolution = 'conflict'
    }

    regions.push({ kind: 'changed', resolution, mine: mineLines, base: baseLines, theirs: theirsLines })
  }

  stable(pos, base.length)
  return regions
}

function same(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/** The merged document, with conflicts marked. `withBase` picks diff3 style. */
export function render(regions, withBase) {
  const out = []
  for (const region of regions) {
    if (region.kind === 'stable') {
      out.push(...region.lines)
      continue
    }
    if (region.resolution === 'conflict') {
      out.push('<<<<<<< mine')
      out.push(...region.mine)
      if (withBase) {
        out.push('||||||| base')
        out.push(...region.base)
      }
      out.push('=======')
      out.push(...region.theirs)
      out.push('>>>>>>> theirs')
    } else if (region.resolution === 'theirs') {
      out.push(...region.theirs)
    } else {
      out.push(...region.mine)
    }
  }
  return out
}

/** One descriptive line per region. */
export function describe(regions) {
  return regions.map(region => {
    if (region.kind === 'stable') return `stable ${region.lines.length}`
    switch (region.resolution) {
      case 'conflict':
        return `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`
      case 'theirs':
        return `theirs ${region.theirs.length}`
      case 'both':
        return `both ${region.mine.length}`
      default:
        return `mine ${region.mine.length}`
    }
  })
}

export function hasConflict(regions) {
  return regions.some(region => region.kind === 'changed' && region.resolution === 'conflict')
}
"}

